const typeMeta = {
  image: { icon: Image },
  video: { icon: Play },
} as const

const providerLabels = {
  unsplash: "Unsplash",
  pexels: "Pexels",
} as const

const providerHomes = {
  unsplash: "https://unsplash.com",
  pexels: "https://www.pexels.com",
} as const

function dimensions(result: PortalOnlineMediaResult) {
  if (!result.width || !result.height) return null
  return `${result.width} × ${result.height}`
}

export function OnlineMediaSearchPage() {
  const t = useTranslations("files.online")
  const router = useRouter()
  const [query, setQuery] = useState("")
  const [results, setResults] = useState<PortalOnlineMediaResult[]>([])
  const [total, setTotal] = useState(0)
  const [hasSearched, setHasSearched] = useState(false)
  const [isSearching, setIsSearching] = useState(false)
  const [canSearch, setCanSearch] = useState(true)
  const [notConfigured, setNotConfigured] = useState(false)
  const [searchError, setSearchError] = useState(false)
  const [importingId, setImportingId] = useState<string | null>(null)
  const [importedIds, setImportedIds] = useState<string[]>([])

  const handleError = useCallback(
    (error: unknown) => {
      if (error instanceof ApiError && error.code === "AUTH_SESSION_EXPIRED") {
        router.replace(loginPath())
        return true
      }
      if (error instanceof ApiError && error.status === 403) {
        setCanSearch(false)
        return true
      }
      return false
    },
    [router]
  )

  const search = useCallback(
    async (term: string) => {
      const normalized = term.trim()
      if (!normalized) {
        setResults([])
        setTotal(0)
        setHasSearched(false)
        return
      }

      setIsSearching(true)
      setSearchError(false)
      setNotConfigured(false)
      try {
        const response = await onlineMediaApi.search({ q: normalized })
        setResults(response.results)
        setTotal(response.total)
        setCanSearch(true)
      } catch (error) {
        if (handleError(error)) return
        if (
          error instanceof ApiError &&
          error.code === "ONLINE_MEDIA_PROVIDER_NOT_CONFIGURED"
        ) {
          setResults([])
          setTotal(0)
          setNotConfigured(true)
          return
        }
        console.error("Online media search failed", error)
        setResults([])
        setTotal(0)
        setSearchError(true)
      } finally {
        setHasSearched(true)
        setIsSearching(false)
      }
    },
    [handleError]
  )

  useEffect(() => {
    const timer = setTimeout(() => void search(query), 400)
    return () => clearTimeout(timer)
  }, [query, search])

  async function importResult(result: PortalOnlineMediaResult) {
    if (importedIds.includes(result.id)) return
    setImportingId(result.id)
    try {
      await onlineMediaApi.import({
        authorName: result.authorName,
        authorUrl: result.authorUrl,
        downloadUrl: result.downloadUrl,
        id: result.id,
        mimeType: result.mimeType,
        provider: result.provider,
        sourceUrl: result.sourceUrl,
        title: result.title,
        type: result.type,
      })
      setImportedIds((current) => [...current, result.id])
      toast.success(t("savedToLibrary", { title: result.title }))
    } catch (error) {
      if (handleError(error)) return
      console.error("Online media import failed", error)
      toast.error(t("importFailed"))
    } finally {
      setImportingId(null)
    }
  }

  if (!canSearch) return <FilesPermissionState mode="search" />

  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
        <InputGroup className="max-w-2xl">
          <InputGroupAddon>
            <Search />
          </InputGroupAddon>
          <InputGroupInput
            aria-label={t("searchLabel")}
            onChange={(event) => setQuery(event.target.value)}
            placeholder={t("searchPlaceholder")}
            value={query}
          />
        </InputGroup>
        <Button asChild variant="brand-secondary">
          <Link href="/portal/files">
            <ArrowLeft data-icon="inline-start" />
            {t("backToFiles")}
          </Link>
        </Button>
      </div>

      {hasSearched && results.length ? (
        <div className="flex flex-wrap items-center justify-between gap-2">
          <p className="font-medium">
            {total} {total === 1 ? "resultado" : "resultados"}
          </p>
          <p className="text-sm text-muted-foreground">{t("importHint")}</p>
        </div>
      ) : null}

      {isSearching ? (
        <PageLoading aria-label={t("searching")} />
      ) : notConfigured ? (
        <EmptyState
          description={t("notConfiguredDescription")}
          icon={Search}
          title={t("notConfiguredTitle")}
        />
      ) : searchError ? (
        <EmptyState
          action={
            <RetryButton
              onClick={() => void search(query)}
              variant="brand-secondary"
            />
          }
          description={t("searchFailedDescription")}
          icon={Search}
          title={t("searchFailedTitle")}
        />
      ) : !hasSearched ? (
        <EmptyState
          description={t("emptyDescription")}
          icon={Search}
          title={t("emptyTitle")}
        />
      ) : results.length === 0 ? (
        <EmptyState
          description={t("noResultsDescription")}
          icon={Search}
          title={t("noResultsTitle")}
        />
      ) : (
        <CardGrid layout="xl-3">
          {results.map((result) => {
            const { icon: MediaIcon } = typeMeta[result.type]
            const label = t(`type.${result.type}`)
            const imported = importedIds.includes(result.id)
            const importing = importingId === result.id
            const size = dimensions(result)

            return (
              <Card key={`${result.provider}-${result.id}`} variant="subtle">
                <CardHeader>
                  <div className="relative flex h-32 items-center justify-center overflow-hidden rounded-lg bg-muted">
                    <MediaIcon
                      aria-hidden="true"
                      className="size-8 text-muted-foreground"
                    />
                    {/* eslint-disable-next-line @next/next/no-img-element -- la vista previa viene del proveedor externo buscado, con dominio arbitrario. */}
                    <img
                      alt={result.title}
                      className="absolute inset-0 size-full object-cover"
                      loading="lazy"
                      onError={(event) => {
                        event.currentTarget.style.display = "none"
                      }}
                      src={result.previewUrl}
                    />
                  </div>
                  <div className="flex items-start justify-between gap-3">
                    <CardTitle className="truncate">{result.title}</CardTitle>
                    <Badge variant="neutral">{label}</Badge>
                  </div>
                  <CardDescription>
                    <Link
                      className="underline-offset-4 hover:underline"
                      href={providerHomes[result.provider]}
                      rel="noopener noreferrer"
                      target="_blank"
                    >
                      {t("providedBy", {
                        provider: providerLabels[result.provider],
                      })}
                    </Link>
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm text-muted-foreground">
                    {result.authorUrl ? (
                      <Link
                        className="underline-offset-4 hover:underline"
                        href={result.authorUrl}
                        rel="noopener noreferrer"
                        target="_blank"
                      >
                        {t("byAuthor", { author: result.authorName })}
                      </Link>
                    ) : (
                      <span>
                        {t("byAuthor", { author: result.authorName })}
                      </span>
                    )}
                    {size ? <span>{size}</span> : null}
                    <Link
                      className="underline-offset-4 hover:underline"
                      href={result.sourceUrl}
                      rel="noopener noreferrer"
                      target="_blank"
                    >
                      {t("viewSource")}
                    </Link>
                  </div>
                </CardContent>
                <CardFooter className="justify-between">
                  <span className="text-xs text-muted-foreground">
                    {imported ? t("inLibrary") : t("available")}
                  </span>
                  <Button
                    disabled={imported || importing}
                    onClick={() => void importResult(result)}
                    size="sm"
                    variant={imported ? "success" : "brand-secondary"}
                  >
                    {importing ? (
                      <Spinner data-icon="inline-start" />
                    ) : imported ? (
                      <Check data-icon="inline-start" />
                    ) : (
                      <Image data-icon="inline-start" />
                    )}
                    {imported ? t("imported") : t("import")}
                  </Button>
                </CardFooter>
              </Card>
            )
          })}
        </CardGrid>
      )}
    </div>
  )
}

